import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {openDatabase} from '../server/db.mjs';
import {extractFunctionOwnerTransfers,migrate} from '../server/migrations.mjs';
import {PLATFORM_MIGRATIONS} from '../server/migration-manifest.mjs';
import {PLANS} from '../shared/plans.js';
test('numbered schema migrations are idempotent and reject changed applied SQL',async()=>{
 const db=await openDatabase({memory:true});
 try{
  const first={version:'fixture-001',sql:"-- SQL comments may contain ; safely\ncreate table fixture(id integer primary key); create table fixture_note(body text); insert into fixture_note values('a;b');"};
  await migrate(db,[first]);await migrate(db,[first]);
  assert.equal((await db.query("select body from fixture_note")).rows[0].body,'a;b');
  assert.equal((await db.query("select count(*)::int as n from platform_migrations where version='fixture-001'")).rows[0].n,1);
  await assert.rejects(migrate(db,[{...first,sql:'drop table fixture'}]),/changed/);
  await migrate(db,[first,{version:'fixture-002',sql:'alter table fixture add column title text'}]);
  await db.query("insert into fixture values(1,'upgraded')");assert.equal((await db.query('select title from fixture')).rows[0].title,'upgraded');
 }finally{await db.close();}
});

test('runtime cannot insert/update the account role or delete accounts',async()=>{
 const db=await openDatabase({memory:true});
 try{
  await db.query("delete from platform_migrations where version='013-runtime-account-column-grants'");
  await db.query('create role lumiq_runtime');
  await db.query('grant select,insert,update,delete on table accounts to lumiq_runtime');
  await db.query("create policy runtime_account_test on accounts to lumiq_runtime using(true) with check(true)");
  const sql=await readFile(new URL('../server/migrations/013-runtime-account-column-grants.sql',import.meta.url),'utf8');
  await migrate(db,[{version:'013-runtime-account-column-grants',sql}]);
  const permissions=(await db.query(`select
   has_column_privilege('lumiq_runtime','accounts','role','insert') as can_insert_role,
   has_column_privilege('lumiq_runtime','accounts','role','update') as can_update_role,
   has_table_privilege('lumiq_runtime','accounts','delete') as can_delete_account,
   has_column_privilege('lumiq_runtime','accounts','name','update') as can_update_name,
   has_column_privilege('lumiq_runtime','accounts','email','insert') as can_insert_email`)).rows[0];
  assert.equal(permissions.can_insert_role,false);
  assert.equal(permissions.can_update_role,false);
  assert.equal(permissions.can_delete_account,false);
  assert.equal(permissions.can_update_name,true);
  assert.equal(permissions.can_insert_email,true);
  await db.query('set role lumiq_runtime');
  const id='30000000-0000-4000-8000-000000000013';
  await db.query('insert into accounts(id,email,name,password_hash,profile,preferences,verified) values($1,$2,$3,$4,$5,$6,$7)',[id,'runtime@example.test','Runtime','hash',{}, {},true]);
  await assert.rejects(db.query('update accounts set role=\'admin\' where id=$1',[id]),/permission denied/);
  await assert.rejects(db.query('delete from accounts where id=$1',[id]),/permission denied/);
  await db.query('reset role');
  assert.equal((await db.query('select role from accounts where id=$1',[id])).rows[0].role,'customer');
  await migrate(db,[{version:'013-runtime-account-column-grants',sql}]);
 }finally{await db.close();}
});

